#!/usr/bin/env node
// Static file server: node serve.js --port 0 --root DIR
'use strict';

const http = require('http');
const fs = require('fs');
const path = require('path');

function parseArgs(argv) {
  const args = { port: 0, root: process.cwd() };
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--port') {
      args.port = parseInt(argv[++i], 10);
      if (!Number.isInteger(args.port) || args.port < 0 || args.port > 65535) {
        console.error('invalid --port');
        process.exit(1);
      }
    } else if (argv[i] === '--root') {
      args.root = argv[++i];
    } else {
      console.error('unknown argument: ' + argv[i]);
      process.exit(1);
    }
  }
  return args;
}

const CONTENT_TYPES = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'text/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
};

function contentTypeFor(p) {
  return CONTENT_TYPES[path.extname(p).toLowerCase()] || 'application/octet-stream';
}

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

const MIME = parseArgs(process.argv.slice(2));
const ROOT = path.resolve(MIME.root);

if (!fs.statSync(ROOT).isDirectory()) {
  console.error('--root must be a directory');
  process.exit(1);
}

function send(res, status, headers, body) {
  res.writeHead(status, headers);
  if (body !== undefined && body !== null) {
    const buf = Buffer.isBuffer(body) ? body : Buffer.from(String(body));
    headers['Content-Length'] = String(buf.length); // set before writeHead? no — see below
  }
}

function respond(res, status, extraHeaders, body) {
  const headers = Object.assign({}, extraHeaders);
  let payload = null;
  if (body !== undefined && body !== null) {
    payload = Buffer.isBuffer(body) ? body : Buffer.from(String(body));
    headers['Content-Length'] = String(payload.length);
  }
  res.writeHead(status, headers);
  if (payload) res.end(payload);
  else res.end();
}

const server = http.createServer((req, res) => {
  let urlPath;
  try {
    urlPath = decodeURIComponent(req.url.split('?')[0]);
  } catch {
    respond(res, 400, {}, 'bad request\n');
    return;
  }

  // Reject NUL bytes and any remaining control chars.
  // eslint-disable-next-line no-control-regex
  if (/[\u0000-\u001f]/.test(urlPath)) {
    respond(res, 403, {}, 'forbidden\n');
    return;
  }

  const resolved = path.resolve(ROOT, '.' + path.posix.normalize('/' + urlPath));

  // Hard traversal protection: resolution outside root is always forbidden.
  // (decodeURIComponent above means %2e%2e forms are caught too.)
  if (resolved !== ROOT && !resolved.startsWith(ROOT + path.sep)) {
    respond(res, 403, {}, 'forbidden\n');
    return;
  }

  fs.stat(resolved, (err, st) => {
    if (err || !st.isFile() && !st.isDirectory()) {
      respond(res, 404, {}, 'not found\n');
      return;
    }

    if (st.isDirectory()) {
      const index = path.join(resolved, 'index.html');
      fs.stat(index, (e2, st2) => {
        if (!e2 && st2.isFile()) {
          serveFile(req, res, index, '/');
          return;
        }
        listDirectory(req, res, resolved);
      });
      return;
    }
    serveFile(req, res, resolved, urlPath);
  });
});

function serveFile(req, res, filePath) {
  fs.readFile(filePath, (err, data) => {
    if (err) {
      respond(res, err.code === 'EACCES' ? 403 : 500, {}, 'error\n');
      return;
    }
    respond(res, 200, { 'Content-Type': contentTypeFor(filePath) }, data);
  });
}

function listDirectory(req, res, dirPath) {
  fs.readdir(dirPath, { withFileTypes: true }, (err, entries) => {
    if (err) {
      respond(res, 500, {}, 'error\n');
      return;
    }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    const items = entries.map(en => {
      const name = en.name + (en.isDirectory() ? '/' : '');
      return `<li><a href="${escapeHtml(encodeURI(name))}">${escapeHtml(name)}</a></li>`;
    }).join('\n');
    const rel = path.relative(ROOT, dirPath) || '.';
    const html =
      `<!DOCTYPE html>\n<html>\n<head><meta charset="utf-8"><title>Index of /${escapeHtml(rel === '.' ? '' : rel)}</title></head>\n` +
      `<body>\n<h1>Index of /${escapeHtml(rel === '.' ? '' : rel)}</h1>\n<ul>\n<li><a href="../">../</a></li>\n${items}\n</ul>\n</body>\n</html>\n`;
    respond(res, 200, { 'Content-Type': 'text/html' }, html);
  });
}

server.listen(MIME.port, () => {
  const addr = server.address();
  console.log(`serving ${ROOT} on port ${addr.port}`);
});

